INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2736763, 380950, 35947, '<td valign="top">Very cool!  Can''t wait to see how you did this!</td>', 'Very cool!  Can''t wait to see how you did this!', '2006-08-17 14:05:54.000000', NULL, 1),
(2736769, 380854, 35947, '<td valign="top">Personally I''d do away with the over-powering border.  You image is very nicely done (composition/lighting).  It might lack some "wow" factor to grab higher points from the tough voters.</td>', 'Personally I''d do away with the over-powering border.  You image is very nicely done (composition/lighting).  It might lack some "wow" factor to grab higher points from the tough voters.', '2006-08-17 14:08:18.000000', NULL, 1),
(2736780, 379189, 35947, '<td valign="top">Very cool!  Personally I think a different composition/crop would work better due to the little bit of negative space at the bottom and left side.  Maybe crop right side off where the solid part of the rainbow ends.  Also flipping it right to left so that the words read left to right properly.</td>', 'Very cool!  Personally I think a different composition/crop would work better due to the little bit of negative space at the bottom and left side.  Maybe crop right side off where the solid part of the rainbow ends.  Also flipping it right to left so that the words read left to right properly.', '2006-08-17 14:11:41.000000', NULL, 1),
(2736876, 381270, 63384, '<td valign="top">wicked sh!t! thats so cool!</td>', 'wicked sh!t! thats so cool!', '2006-08-17 14:47:20.000000', NULL, 1),
(2736885, 381222, 27373, '<td valign="top">I am guessing a pair of mirros used on this one.  Well done, good use of props.  Although I don''t really understand the connection of the title, but I don''t vote on titles.</td>', 'I am guessing a pair of mirros used on this one.  Well done, good use of props.  Although I don''t really understand the connection of the title, but I don''t vote on titles.', '2006-08-17 14:48:35.000000', NULL, 1),
(2736916, 381215, 27373, '<td valign="top">Good idea, although I think the flash in the lens is a bit much.  I probably would''ve tried for a strong exposure on the camera itself and then also had the "fire" from the flash.</td>', 'Good idea, although I think the flash in the lens is a bit much.  I probably would''ve tried for a strong exposure on the camera itself and then also had the "fire" from the flash.', '2006-08-17 14:54:09.000000', NULL, 1),
(2736937, 381152, 27373, '<td valign="top">I love this shot.  Just the additional thoughts that it puts into my head makes it worthy of a 10.  I can just picture myself out hiking and seeing somebody walking along the train packing a TV and a photo bag.  Very clever idea and very well done.</td>', 'I love this shot.  Just the additional thoughts that it puts into my head makes it worthy of a 10.  I can just picture myself out hiking and seeing somebody walking along the train packing a TV and a photo bag.  Very clever idea and very well done.', '2006-08-17 14:57:52.000000', NULL, 1),
(2736947, 380042, 27373, '<td valign="top">Bonus point for the hat.  And a second for being a Pentax Guy.  Well done image, very good lighting.</td>', 'Bonus point for the hat.  And a second for being a Pentax Guy.  Well done image, very good lighting.', '2006-08-17 14:59:40.000000', NULL, 1),
(2736948, 378502, 27373, '<td valign="top">I really like this idea, wish there was less clutter in the reflection.</td>', 'I really like this idea, wish there was less clutter in the reflection.', '2006-08-17 14:59:44.000000', NULL, 1),
(2736949, 381244, 27373, '<td valign="top">Nice, looks like a canon ad.</td>', 'Nice, looks like a canon ad.', '2006-08-17 14:59:55.000000', NULL, 1),
