(2736951, 378874, 27373, '<td valign="top">This was a really good idea, I think the execution of it could be better.  The blurry foreground image was good, but this is too blurry for my tastes.</td>', 'This was a really good idea, I think the execution of it could be better.  The blurry foreground image was good, but this is too blurry for my tastes.', '2006-08-17 15:00:01.000000', NULL, 1),
(2736952, 381130, 27373, '<td valign="top">Another interesting take on the reflection idea.  Two problems, too much clutter in the background and too many scratches on the spoon.</td>', 'Another interesting take on the reflection idea.  Two problems, too much clutter in the background and too many scratches on the spoon.', '2006-08-17 15:00:04.000000', NULL, 1),
