INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2738793, 381033, 21606, '<td valign="top">This is creative.</td>', 'This is creative.', '2006-08-18 02:08:17.000000', NULL, 1),
(2738795, 377882, 21606, '<td valign="top">This is a very nice studio shot. Canon would be proud.</td>', 'This is a very nice studio shot. Canon would be proud.', '2006-08-18 02:08:38.000000', NULL, 1),
(2738796, 380026, 21606, '<td valign="top">GREAT Picture! Good Job.</td>', 'GREAT Picture! Good Job.', '2006-08-18 02:08:54.000000', NULL, 1),
(2738934, 381238, 16004, '<td valign="top">gave this a ten!  it''s a gorgeously sensual image, really is.  i might like it a bit more if it was some harlot with black finger nail polish, but as it is it''s wonderful.  the lighting is fantastic, the sepia tones work wonderfully well, composition can''t be faulted.  a totally flawless image with mood, feeling and buckets of style.</td>', 'gave this a ten!  it''s a gorgeously sensual image, really is.  i might like it a bit more if it was some harlot with black finger nail polish, but as it is it''s wonderful.  the lighting is fantastic, the sepia tones work wonderfully well, composition can''t be faulted.  a totally flawless image with mood, feeling and buckets of style.', '2006-08-18 04:56:38.000000', NULL, 1),
(2738938, 381097, 16004, '<td valign="top">i gave this an 9.  generally i''m a total sucker for IR, and this is a super crisp nicely bright and lovely example of how good it can look.  the environment is very invitingly pretty.  the reason i didn''t give a ten was i felt that the environment is slightly too prominently vying for the attention of the viewer, almost making the self portrait element inconsequential. i personally love how the camera is popping into shot; it''s actually a really cute way of doing it, but for the challenge i''m in two minds.  and also i really feel a longer exposure might have enhanced the glossy feel a bit (i would guess that everyone likes billiard table smooth water in these sort of shots; adds to the odd surrealism you get in IR). still, great stuff.</td>', 'i gave this an 9.  generally i''m a total sucker for IR, and this is a super crisp nicely bright and lovely example of how good it can look.  the environment is very invitingly pretty.  the reason i didn''t give a ten was i felt that the environment is slightly too prominently vying for the attention of the viewer, almost making the self portrait element inconsequential. i personally love how the camera is popping into shot; it''s actually a really cute way of doing it, but for the challenge i''m in two minds.  and also i really feel a longer exposure might have enhanced the glossy feel a bit (i would guess that everyone likes billiard table smooth water in these sort of shots; adds to the odd surrealism you get in IR). still, great stuff.', '2006-08-18 05:14:37.000000', NULL, 1),
(2738940, 380972, 16004, '<td valign="top">i gave this a 6...  i liked it; more for the post editting than the actual shot itself though.  the picture seemed not really all that much thought about, to be honest. it keeps a sense of heightened urgency and realism, i suppose.  but like i said, it''s the editting that sets it apart from the run of the mill; i think it''s effectively done; though one suspects might have been moreso if went monochrome.  also, i''d have taken off the camera strap; looks like big floppy bunny ears which probably isn''t the look you were going for.  might be wrong; you might like big bunny ears (i know i do, they''re lovely) and you might have wanted to maximise cute bunny ear awareness amongst dpcers.  it''s worked.  can''t stop thinkng about them now.  anyway, 6.</td>', 'i gave this a 6...  i liked it; more for the post editting than the actual shot itself though.  the picture seemed not really all that much thought about, to be honest. it keeps a sense of heightened urgency and realism, i suppose.  but like i said, it''s the editting that sets it apart from the run of the mill; i think it''s effectively done; though one suspects might have been moreso if went monochrome.  also, i''d have taken off the camera strap; looks like big floppy bunny ears which probably isn''t the look you were going for.  might be wrong; you might like big bunny ears (i know i do, they''re lovely) and you might have wanted to maximise cute bunny ear awareness amongst dpcers.  it''s worked.  can''t stop thinkng about them now.  anyway, 6.', '2006-08-18 05:28:01.000000', NULL, 1),
(2738941, 380566, 16004, '<td valign="top">my "hope this blue ribbons" of the challenge.  i love EVERYthing about this image; it''s so rich in personality, mood, style...  technically it''s visually superb; the high contrast is effective, the slight level of noise comfortably unobtrusive.  it''s sharp, well composed, feels wide angly but natural.  the set up is the incredible thing though; i love how the camera has a personality all of it''s own, i love how there is much going on and to look at, but it doesn''t detract from the portrait element of your camera.  it''s taking centre stage, but not stealing the show...  it feels real life; the expression and your posture of the girl on the left is fantastic and complements the mood brilliantly.  think she''s very photogenic, actually.  there''s so much to enjoy; even the horse cushion somehow fits into the frame and with what''s going on...  i love how you used the strap to support the lens; it''s almost like it''s reclining.  really is fantastic stuff.  10</td>', 'my "hope this blue ribbons" of the challenge.  i love EVERYthing about this image; it''s so rich in personality, mood, style...  technically it''s visually superb; the high contrast is effective, the slight level of noise comfortably unobtrusive.  it''s sharp, well composed, feels wide angly but natural.  the set up is the incredible thing though; i love how the camera has a personality all of it''s own, i love how there is much going on and to look at, but it doesn''t detract from the portrait element of your camera.  it''s taking centre stage, but not stealing the show...  it feels real life; the expression and your posture of the girl on the left is fantastic and complements the mood brilliantly.  think she''s very photogenic, actually.  there''s so much to enjoy; even the horse cushion somehow fits into the frame and with what''s going on...  i love how you used the strap to support the lens; it''s almost like it''s reclining.  really is fantastic stuff.  10', '2006-08-18 05:38:28.000000', NULL, 1),
(2738946, 379759, 16004, '<td valign="top">i gave this an 8.  the decision to go use the negative filter works effectively; the shades of blue against the white are visually very nice.  i especially liked the inclusion of the strap, with the brand name positioned just so; an exemplary bit of composition and setting up, and good thinking!  the green splodges in the area of the lens are a bit off putting, but that aside, very nice and creative photography. :)</td>', 'i gave this an 8.  the decision to go use the negative filter works effectively; the shades of blue against the white are visually very nice.  i especially liked the inclusion of the strap, with the brand name positioned just so; an exemplary bit of composition and setting up, and good thinking!  the green splodges in the area of the lens are a bit off putting, but that aside, very nice and creative photography. :)', '2006-08-18 05:47:59.000000', NULL, 1),
(2738951, 377996, 16004, '<td valign="top">i originally gave this an 8, but in retrospect, think it deserves upping to a 9.  i initially knocked it down because i wasn''t particularly keen on the purple hue, but you know, i''m warming to it.  i think the colours suit the melancholy feel of the shot, and the general ambience going on.  i love the composition too; the out of focusness of the camera works a treat in that to me it suggests a sort of binding companionship between the photographer and the camera. actually, it''s sort of composed in a sixties french moody artfilm drama type thing (for real style overdrive, i just wish you had an old Leica instead of a modern silver canon!).  the lighting is also incredible; the light to dark across the shot engrossingly effective.  it''s all so stylish, so captivatingly lovely.  screw the 9: 10. <br/> <br/>btw, cool specs!</td>', 'i originally gave this an 8, but in retrospect, think it deserves upping to a 9.  i initially knocked it down because i wasn''t particularly keen on the purple hue, but you know, i''m warming to it.  i think the colours suit the melancholy feel of the shot, and the general ambience going on.  i love the composition too; the out of focusness of the camera works a treat in that to me it suggests a sort of binding companionship between the photographer and the camera. actually, it''s sort of composed in a sixties french moody artfilm drama type thing (for real style overdrive, i just wish you had an old Leica instead of a modern silver canon!).  the lighting is also incredible; the light to dark across the shot engrossingly effective.  it''s all so stylish, so captivatingly lovely.  screw the 9: 10.  btw, cool specs!', '2006-08-18 05:57:29.000000', NULL, 1),
(2738953, 379293, 42125, '<td valign="top">Is it a candid camera in your hair?</td>', 'Is it a candid camera in your hair?', '2006-08-18 06:01:58.000000', NULL, 1),
(2738959, 381251, 42125, '<td valign="top">Where is it? :-)</td>', 'Where is it? :-)', '2006-08-18 06:07:20.000000', NULL, 1),
(2738961, 380945, 16004, '<td valign="top">gave this a 7.  it''s a technically really good picture, but somehow doesn''t feel quite dynamic enough.  it''s nice and sharp, i like the bottom / corner compostion, and the yellow background a lovely striking contrast to the black of the camera, but aside from that feels a bit flat and lifeless.  the presence of the strap lets down the clean line, modern, uncluttered feel of the picture a bit, too.  i''d personally had also cropped below the area of red in the top corner; it detracts and there''s also a lighter splodge in the top-middle area...</td>', 'gave this a 7.  it''s a technically really good picture, but somehow doesn''t feel quite dynamic enough.  it''s nice and sharp, i like the bottom / corner compostion, and the yellow background a lovely striking contrast to the black of the camera, but aside from that feels a bit flat and lifeless.  the presence of the strap lets down the clean line, modern, uncluttered feel of the picture a bit, too.  i''d personally had also cropped below the area of red in the top corner; it detracts and there''s also a lighter splodge in the top-middle area...', '2006-08-18 06:16:29.000000', NULL, 1),
(2738966, 381018, 16004, '<td valign="top">gave this an 8.  i love the dirty grungy feel of this.  the look and presentation of the camera on the right is wonderful, especially with the blue glow behind it.  oh, it just occured to me; is this a clever optical illusion, do you have two identical cameras?  if so, very good; if not, even very gooder!  using light bulbs is an originally creative novelty which i like, though the messy clutter feel of the room reflected in the bulb kind of lessens the impact overall.  still; great picture!</td>', 'gave this an 8.  i love the dirty grungy feel of this.  the look and presentation of the camera on the right is wonderful, especially with the blue glow behind it.  oh, it just occured to me; is this a clever optical illusion, do you have two identical cameras?  if so, very good; if not, even very gooder!  using light bulbs is an originally creative novelty which i like, though the messy clutter feel of the room reflected in the bulb kind of lessens the impact overall.  still; great picture!', '2006-08-18 06:36:37.000000', NULL, 1),
(2738979, 380883, 42125, '<td valign="top">A bit of misundarstanding I think!</td>', 'A bit of misundarstanding I think!', '2006-08-18 07:23:18.000000', NULL, 1),
(2738982, 380944, 53969, '<td valign="top">I love this photo! It is a bit of refreshing humour! It kind of reminds me of Mr.potato Head out of Toy Story and his wife. Great idea!</td>', 'I love this photo! It is a bit of refreshing humour! It kind of reminds me of Mr.potato Head out of Toy Story and his wife. Great idea!', '2006-08-18 07:30:31.000000', NULL, 1),
(2738985, 381106, 55838, '<td valign="top">Back to bump you up.  I think I went by this too fast the first time and didn''t think about what you did here.  Extra point for the creativity.  Cool idea.</td>', 'Back to bump you up.  I think I went by this too fast the first time and didn''t think about what you did here.  Extra point for the creativity.  Cool idea.', '2006-08-18 07:38:58.000000', NULL, 1),
(2739005, 380104, 29591, '<td valign="top">It is very funny, so that it made me comment. I like it but I guess the blown out sky will cost you some points cause it is very distracting and thakes my eyes from your camera (subject). Having said that, I like the creativity and overall composition maybe I would have level the mirror with the can? to the left. Good luck And cause today is friday and has been a good week you have a 9 from me. :)</td>', 'It is very funny, so that it made me comment. I like it but I guess the blown out sky will cost you some points cause it is very distracting and thakes my eyes from your camera (subject). Having said that, I like the creativity and overall composition maybe I would have level the mirror with the can? to the left. Good luck And cause today is friday and has been a good week you have a 9 from me. :)', '2006-08-18 08:00:20.000000', NULL, 1),
(2739008, 381275, 16004, '<td valign="top">gave this a 9, based on the immediate wowness of style more than anything else.  the colours dramatically enhance the image as does the very funky lovely background.  the panoramic look is also very nice, and a great decision.  i''m in two minds about the oddness at the top of the camera; it''s obviously a flaw but such a good one i think it actually adds to the overall shot.</td>', 'gave this a 9, based on the immediate wowness of style more than anything else.  the colours dramatically enhance the image as does the very funky lovely background.  the panoramic look is also very nice, and a great decision.  i''m in two minds about the oddness at the top of the camera; it''s obviously a flaw but such a good one i think it actually adds to the overall shot.', '2006-08-18 08:01:50.000000', NULL, 1),
(2739021, 381097, 29591, '<td valign="top">Wow, I really have to get an IR filter or learn how to fake this :)<br/>Really nice but specially not boring at all. The overall picture is good but it is more about the landscape than about your camera. Having said that, the title saves the day so high marks from me, good luck</td>', 'Wow, I really have to get an IR filter or learn how to fake this :)Really nice but specially not boring at all. The overall picture is good but it is more about the landscape than about your camera. Having said that, the title saves the day so high marks from me, good luck', '2006-08-18 08:09:33.000000', NULL, 1),
