(2745960, 380947, 64035, '<td valign="top">Nice enough image, but there''s nothing special about it, and it isn''t quite cute enough to be elevated because of amusement factor.</td>', 'Nice enough image, but there''s nothing special about it, and it isn''t quite cute enough to be elevated because of amusement factor.', '2006-08-21 12:43:24.000000', NULL, 1),
(2745962, 381203, 64035, '<td valign="top">Clever idea, and well shot. I like the blue very much. To get a very top mark, one of the other drops being in picture, or the whole thing being closer would be needed - there''s just too much expanse of blur for my taste. Good shot, though - well done!</td>', 'Clever idea, and well shot. I like the blue very much. To get a very top mark, one of the other drops being in picture, or the whole thing being closer would be needed - there''s just too much expanse of blur for my taste. Good shot, though - well done!', '2006-08-21 12:45:22.000000', NULL, 1),
(2745966, 379274, 64035, '<td valign="top">Nice light, but I found it difficult to look at - the out of focus lens is unpleasant to look at, but it gets in the way of looking at the nice effect on the leather.</td>', 'Nice light, but I found it difficult to look at - the out of focus lens is unpleasant to look at, but it gets in the way of looking at the nice effect on the leather.', '2006-08-21 12:46:05.000000', NULL, 1),
(2745968, 377895, 64035, '<td valign="top">A little ho-hum, though technically competent. I''m intrigued about the place - almost looks like a theatre foyer in the reflected background.</td>', 'A little ho-hum, though technically competent. I''m intrigued about the place - almost looks like a theatre foyer in the reflected background.', '2006-08-21 12:47:04.000000', NULL, 1),
(2745969, 378985, 64035, '<td valign="top">Nice light, good sharp silhouette. Not sure that there''s anything deeper here.</td>', 'Nice light, good sharp silhouette. Not sure that there''s anything deeper here.', '2006-08-21 12:47:42.000000', NULL, 1),
(2745971, 381035, 64035, '<td valign="top">Horrible double effect caused by the mirror on the nameplate mars this, rather. It''s a little bit "here is a picture of my camera", though the background cloth is a pleasant colour.</td>', 'Horrible double effect caused by the mirror on the nameplate mars this, rather. It''s a little bit "here is a picture of my camera", though the background cloth is a pleasant colour.', '2006-08-21 12:48:45.000000', NULL, 1),
(2745977, 381244, 64035, '<td valign="top">Simple? Yes. Slightly dull though. I wish you had made more of the texture of the camera - there''s almost a wonderful leathery feel, and a closer look in the same style would have had some more atmosphere.</td>', 'Simple? Yes. Slightly dull though. I wish you had made more of the texture of the camera - there''s almost a wonderful leathery feel, and a closer look in the same style would have had some more atmosphere.', '2006-08-21 12:50:03.000000', NULL, 1),
(2745981, 381238, 64035, '<td valign="top">It''s very arty, with a good feel. The only problem is that I can''t find an emotion to go with it - it''s as if it wants to be meaningful, without having anything to say. Good light, though!</td>', 'It''s very arty, with a good feel. The only problem is that I can''t find an emotion to go with it - it''s as if it wants to be meaningful, without having anything to say. Good light, though!', '2006-08-21 12:50:59.000000', NULL, 1),
(2745986, 381152, 64035, '<td valign="top">Clever idea! Breaks up the "mirror" photos. Was there nothing more dynamic you could have done with the shot, though? Getting the camera lower would have been something a little different. Still, good thought!</td>', 'Clever idea! Breaks up the "mirror" photos. Was there nothing more dynamic you could have done with the shot, though? Getting the camera lower would have been something a little different. Still, good thought!', '2006-08-21 12:52:25.000000', NULL, 1),
(2745988, 380953, 64035, '<td valign="top">Close to fantastic. I wish you could have found a way to flatten the leaves a little more, as it''s *almost* convincing that the camera is in the painting. Credible try!</td>', 'Close to fantastic. I wish you could have found a way to flatten the leaves a little more, as it''s *almost* convincing that the camera is in the painting. Credible try!', '2006-08-21 12:53:21.000000', NULL, 1),
(2745991, 381202, 64035, '<td valign="top">Nice composition, slightly frustrating execution. Just a little sharper on the camera!</td>', 'Nice composition, slightly frustrating execution. Just a little sharper on the camera!', '2006-08-21 12:54:14.000000', NULL, 1),
(2745999, 380048, 64035, '<td valign="top">Is there something I''m not seeing? Does the shape mean anything? Is it some kind of weird four eyed lion?</td>', 'Is there something I''m not seeing? Does the shape mean anything? Is it some kind of weird four eyed lion?', '2006-08-21 12:55:24.000000', NULL, 1),
(2746004, 379642, 64035, '<td valign="top">Nice sky shot. The silhoutted camera doesn''t seem quite sharp or dark enough.</td>', 'Nice sky shot. The silhoutted camera doesn''t seem quite sharp or dark enough.', '2006-08-21 12:56:10.000000', NULL, 1),
(2746006, 381188, 64035, '<td valign="top">Good expression, and pleasing resultant image. Well done!</td>', 'Good expression, and pleasing resultant image. Well done!', '2006-08-21 12:56:36.000000', NULL, 1),
(2746011, 379860, 22748, '<td valign="top">I''m looking hard, but not seeing a camera anywhere. Maybe you didn''t read the challenge description.</td>', 'I''m looking hard, but not seeing a camera anywhere. Maybe you didn''t read the challenge description.', '2006-08-21 13:00:07.000000', NULL, 1),
(2746013, 381262, 22748, '<td valign="top">Dude, this is brilliant.</td>', 'Dude, this is brilliant.', '2006-08-21 13:02:11.000000', NULL, 1),
(2746023, 379293, 22748, '<td valign="top">I think if you read the challenge description, you will realize you are to take a picture of your camera: "use your camera to take a picture of itself."</td>', 'I think if you read the challenge description, you will realize you are to take a picture of your camera: "use your camera to take a picture of itself."', '2006-08-21 13:07:07.000000', NULL, 1),
(2746040, 381244, 16004, '<td valign="top">the minimalism in this is really great.  the use of a completely black background well suited (and well applied for a change; so often is a black background used that makes the image completely lifeless and dead; not so here).  not sure if it was intentional (stroke of genius if it was) but i love the slightly brownish tint as well, adds so much warmth...  the use of negative space, and the centred composition works terrifically as well.  the only negative thing is, well, it doesn''t really do much in terms of something i can''t quite describe.  stir souls?  entertain, maybe?  i don''t know.  visually it''s very lovely, and i originally thought its worth a 7, but it is so expertly done and stylish, i''ll up it to an 8.</td>', 'the minimalism in this is really great.  the use of a completely black background well suited (and well applied for a change; so often is a black background used that makes the image completely lifeless and dead; not so here).  not sure if it was intentional (stroke of genius if it was) but i love the slightly brownish tint as well, adds so much warmth...  the use of negative space, and the centred composition works terrifically as well.  the only negative thing is, well, it doesn''t really do much in terms of something i can''t quite describe.  stir souls?  entertain, maybe?  i don''t know.  visually it''s very lovely, and i originally thought its worth a 7, but it is so expertly done and stylish, i''ll up it to an 8.', '2006-08-21 13:14:25.000000', NULL, 1),
(2746069, 381152, 60281, '<td valign="top">Nice shot. I think it would have helped the surrealism if the cables were hidden from view.</td>', 'Nice shot. I think it would have helped the surrealism if the cables were hidden from view.', '2006-08-21 13:26:28.000000', NULL, 1),
(2746322, 378808, 57320, '<td valign="top">Good, but very basic.</td>', 'Good, but very basic.', '2006-08-21 15:23:28.000000', NULL, 1),
(2746325, 380130, 57320, '<td valign="top">I can''t really tell there is a camrera on LCD screen</td>', 'I can''t really tell there is a camrera on LCD screen', '2006-08-21 15:24:10.000000', NULL, 1),
(2746328, 381152, 57320, '<td valign="top">Good, it might look even cooler in a studio setting</td>', 'Good, it might look even cooler in a studio setting', '2006-08-21 15:24:54.000000', NULL, 1),
(2746388, 381279, 50289, '<td valign="top">Nice idea.  I would have liked to see a little more detail in the camera though.</td>', 'Nice idea.  I would have liked to see a little more detail in the camera though.', '2006-08-21 16:05:04.000000', NULL, 1),
(2746396, 381152, 50289, '<td valign="top">Very creative!  Only one minor issue...could have cropped out the bright sky in the upper right corner (I know, nit-picky) -9-</td>', 'Very creative!  Only one minor issue...could have cropped out the bright sky in the upper right corner (I know, nit-picky) -9-', '2006-08-21 16:09:49.000000', NULL, 1),
(2746404, 380883, 50289, '<td valign="top">Where''s the camera?</td>', 'Where''s the camera?', '2006-08-21 16:21:02.000000', NULL, 1),
(2746409, 380680, 50289, '<td valign="top">DNMC Where''s the camera?</td>', 'DNMC Where''s the camera?', '2006-08-21 16:24:16.000000', NULL, 1),
(2746429, 379320, 16004, '<td valign="top">i''d rather it didn''t! i have enough trouble getting it to take the pictures i want, let alone give me guidance on spirituality!  of the challenge, this is one of the more madly creative ones out there (if you ignore the one dressed as a baby).  kudos and acknowledgement of a job well done is due regarding the effort gone into the set-up.  but really, it''s just too weird for words.  technically, there''s very little to criticise; i''d like the camera / vicars head be a little sharper, but other than that, it''s fine.  nice bright bold colours of the fabrics is really appealing visually. how it conducts a sermon is just bewildering.  5.</td>', 'i''d rather it didn''t! i have enough trouble getting it to take the pictures i want, let alone give me guidance on spirituality!  of the challenge, this is one of the more madly creative ones out there (if you ignore the one dressed as a baby).  kudos and acknowledgement of a job well done is due regarding the effort gone into the set-up.  but really, it''s just too weird for words.  technically, there''s very little to criticise; i''d like the camera / vicars head be a little sharper, but other than that, it''s fine.  nice bright bold colours of the fabrics is really appealing visually. how it conducts a sermon is just bewildering.  5.', '2006-08-21 16:33:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2746433, 380925, 16004, '<td valign="top">the setting doesn''t really justify the fabulousness of the camera.  the reflective surface on the bottom is a nice touch, but we don''t really see enough of the bottom reflection to justify its presence.  also, the cloth sheet is too grey (white balance issue maybe?) to really make a big impact (and it''s also a bit exposed along the bottom edge on the right). a  sheet of white glossy photo paper might have worked a bit better.  and i don''t think you would have suffered by flipping the picture, so it''s the right way round.  the strap is a distraction too.  sorry.  4.</td>', 'the setting doesn''t really justify the fabulousness of the camera.  the reflective surface on the bottom is a nice touch, but we don''t really see enough of the bottom reflection to justify its presence.  also, the cloth sheet is too grey (white balance issue maybe?) to really make a big impact (and it''s also a bit exposed along the bottom edge on the right). a  sheet of white glossy photo paper might have worked a bit better.  and i don''t think you would have suffered by flipping the picture, so it''s the right way round.  the strap is a distraction too.  sorry.  4.', '2006-08-21 16:38:50.000000', NULL, 1),
