(2748881, 379293, 64035, '<td valign="top">There''s nothing per se wrong with this image, but it doesn''t fit the challenge, and I found it otherwise quite average. I like the different angle, and the sense of motion. I''m unsure about the yellow tinge - slightly nauseating.</td>', 'There''s nothing per se wrong with this image, but it doesn''t fit the challenge, and I found it otherwise quite average. I like the different angle, and the sense of motion. I''m unsure about the yellow tinge - slightly nauseating.', '2006-08-22 13:34:20.000000', NULL, 1),
(2748886, 380914, 64035, '<td valign="top">Interesting dimensions. I''m not sure if the pink blur along the bottom was intentional or not, but it''s offputting.</td>', 'Interesting dimensions. I''m not sure if the pink blur along the bottom was intentional or not, but it''s offputting.', '2006-08-22 13:35:28.000000', NULL, 1),
(2748887, 377996, 13759, '<td valign="top">This picture is awesome. Very good mood and feeling.<br/>But the portrait must be from the camera itself. The focus and DOF here sugests the girl as subject not the camera.</td>', 'This picture is awesome. Very good mood and feeling.But the portrait must be from the camera itself. The focus and DOF here sugests the girl as subject not the camera.', '2006-08-22 13:35:30.000000', NULL, 1),
(2748889, 379860, 64035, '<td valign="top">Maybe just me being stupid, but I can''t see how this fulfills the challenge. Nice light, though, and an interesting angle.</td>', 'Maybe just me being stupid, but I can''t see how this fulfills the challenge. Nice light, though, and an interesting angle.', '2006-08-22 13:35:39.000000', NULL, 1),
(2748890, 379189, 64035, '<td valign="top">Good idea, but the execution isn''t quite clean enough.</td>', 'Good idea, but the execution isn''t quite clean enough.', '2006-08-22 13:35:49.000000', NULL, 1),
(2748896, 378808, 64035, '<td valign="top">There''s nothing awful about this picture, but the lighting is fairly flat, the quality is a bit scratchy (and not in an interesting way) and it just feels very average.</td>', 'There''s nothing awful about this picture, but the lighting is fairly flat, the quality is a bit scratchy (and not in an interesting way) and it just feels very average.', '2006-08-22 13:36:57.000000', NULL, 1),
(2748903, 379444, 13759, '<td valign="top">The camera is a bit hidden, no?</td>', 'The camera is a bit hidden, no?', '2006-08-22 13:40:47.000000', NULL, 1),
(2748909, 380104, 60025, '<td valign="top">Creative.</td>', 'Creative.', '2006-08-22 13:42:35.000000', NULL, 1),
(2748910, 381043, 13759, '<td valign="top">Very good picture. Nice setup with mirrors. The only issue I had here is the DOF. To me it must be more deep to put all camera body in focus. But a great work.</td>', 'Very good picture. Nice setup with mirrors. The only issue I had here is the DOF. To me it must be more deep to put all camera body in focus. But a great work.', '2006-08-22 13:42:57.000000', NULL, 1),
(2748926, 378790, 60025, '<td valign="top">Wow.</td>', 'Wow.', '2006-08-22 13:49:39.000000', NULL, 1),
(2748944, 381155, 13759, '<td valign="top">There is good idea to the shot. But the camera itself is a bit out of focus.</td>', 'There is good idea to the shot. But the camera itself is a bit out of focus.', '2006-08-22 13:59:09.000000', NULL, 1),
(2748948, 380630, 13759, '<td valign="top">The camera is very dark and little to have the title of subject in this picture.</td>', 'The camera is very dark and little to have the title of subject in this picture.', '2006-08-22 14:01:00.000000', NULL, 1),
(2748949, 380104, 64035, '<td valign="top">Fabulous. Sepia is great, the mirror looks amazing and best of all is the furry coat. The area to the right is a bit of a scrubby void, but everything else is great - and it made me laugh!</td>', 'Fabulous. Sepia is great, the mirror looks amazing and best of all is the furry coat. The area to the right is a bit of a scrubby void, but everything else is great - and it made me laugh!', '2006-08-22 14:02:16.000000', NULL, 1),
(2748961, 379666, 13759, '<td valign="top">A very nice picture. Great idea, but the camera relies terciary plane. The glass here fills the primary subject place.</td>', 'A very nice picture. Great idea, but the camera relies terciary plane. The glass here fills the primary subject place.', '2006-08-22 14:10:13.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2748968, 380042, 32345, '<td valign="top">Back for comments.<br/> <br/>This is one of my top choices. I love the composition. Nice focus, even the mirror looks pretty good. Great lighting. Well done.</td>', 'Back for comments. This is one of my top choices. I love the composition. Nice focus, even the mirror looks pretty good. Great lighting. Well done.', '2006-08-22 14:17:52.000000', NULL, 1),
